5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.rest.escalation.DailyLimitExceededException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Rejects a create request once {@link #DAILY_LIMIT} or more owners have already been
11	 * registered on the current date, so the request maps to a 429. Owners are counted by their
12	 * {@code registrationDate}, which defaults to today on creation. Runs among the other create
13	 * guards, before {@link BuildOwner} maps the request to an entity.
14	 */
15	public class EnsureDailyLimit {
16	
17	    /** Maximum number of owners allowed to be registered on a single date. */
18	    static final int DAILY_LIMIT = 100;
19	
20	    public void service(OwnerRepository ownerRepository) throws DailyLimitExceededException {
21	        LocalDate today = LocalDate.now();
22	        int count = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (today.equals(existing.getRegistrationDate())) {
25	                count++;
26	            }
27	        }
28	        if (count >= DAILY_LIMIT) {
29	            throw new DailyLimitExceededException(today, DAILY_LIMIT);
30	        }
31	    }
32	}
