44	    /**
45	     * Derive the membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last
46	     * two digits of the registration date year (e.g. 'SYD-SMI-0007-M26'). Returns null when
47	     * either source field is absent.
48	     */
49	    default String membershipNumber(Owner owner) {
50	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
51	            return null;
