58	     * (namesakeCount is 0) and an email is present, otherwise 'BRONZE'.
59	     */
60	    default String membershipTier(Owner owner) {
61	        boolean unique = Integer.valueOf(0).equals(owner.getNamesakeCount());
62	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
63	        return unique && hasEmail ? "SILVER" : "BRONZE";
64	    }
