11	/**
12	 * Rejects a create request that is missing or blank in any required owner field, before
13	 * {@link BuildOwner} maps the body to an entity. Runs first so the body is read once here
14	 * and republished for later steps. The address is judged blank after normalization (see
15	 * {@link AddressNormalizer}), so an address that collapses to nothing is rejected here.
16	 */
17	public class ValidateNewOwner {
18	
19	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
20	            throws MissingOwnerFieldsException {
21	        List<String> missing = new ArrayList<>();
22	        checkPresent("firstName", request.getFirstName(), missing);
23	        checkPresent("lastName", request.getLastName(), missing);
24	        checkPresent("address", AddressNormalizer.normalize(request.getAddress()), missing);
25	        checkPresent("city", request.getCity(), missing);
26	        checkPresent("telephone", request.getTelephone(), missing);
27	        if (!missing.isEmpty()) {
28	            throw new MissingOwnerFieldsException(missing);
29	        }
30	        validated.set(request);
31	    }
32	
33	    private static void checkPresent(String name, String value, List<String> missing) {
34	        if (value == null || value.isBlank()) {
35	            missing.add(name);
36	        }
37	    }
38	}
